var NOKTA_METIN = [
  ["عَمَلٌ خَيْرٌ مِنْ مَسْأَلَةٍ", "العَمَلُ نِعْمَةٌ مِنْ نِعَمِ اللهِ[[،]] ولا يَعْرِفُ هذِهِ النِّعْمَةَ إِلّا مَنْ فَقَدَها بِسَبَبِ المَرَضِ أَوْ غَيْرِهِ[[.|،]] ومَعَ ذلِكَ[[،]] فَبَعْضُ النّاسِ لا يُحِبّونَ العَمَلَ[[،]] ويَعْتَمِدونَ عَلى غَيْرِهِمْ أَوْ يَتَسَوَّلونَ في الطُّرُقِ[[.]] قالَ الرَّسولُ ﷺ[[: «]]ما أَكَلَ أَحَدٌ طَعامًا قَطُّ خَيْرًا مِنْ أَنْ يَأْكُلَ مِنْ عَمَلِ يَدِهِ[[،]] وإِنَّ نَبِيَّ اللهِ داوُدَ كانَ يَأْكُلُ مِنْ عَمَلِ يَدِهِ[[».]] وقالَ[[: «]]لَأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلَهُ ثُمَّ يَغْدُوَ إِلى الجَبَلِ فَيَحْتَطِبَ[[،]] فَيَبيعَ فَيَأْكُلَ ويَتَصَدَّقَ[[،]] خَيْرٌ مِنْ أَنْ يَسْأَلَ النّاسَ[[».]]"],
  ["", "ذَهَبَ رَجُلٌ فَقيرٌ إِلى رَسولِ اللهِ ﷺ وسَأَلَهُ شَيْئًا[[،|.]] فَقالَ لَهُ الرَّسولُ ﷺ[[: «]]هَلْ في بَيْتِكَ شَيْءٌ[[؟»]] قالَ الأَعْرابِيُّ[[: «]]نَعَمْ[[،]] قَصْعَةٌ [[(]]إِناءٌ[[)]] نَأْكُلُ فيها ونَشْرَبُ مِنْها ونَتَطَهَّرُ[[،]] وحِلْسٌ [[(]]فِراشٌ[[)]] نَجْلِسُ عَلَيْهِ[[،]] ولا شَيْءَ غَيْرُ هذا[[».]] فَقالَ لَهُ الرَّسولُ ﷺ[[: «]]ائْتِني بِهِما[[».]] فَأَتاهُ بِهِما[[،]] فَأَمْسَكَهُما بَيْنَ يَدَيْهِ وقالَ لِأَصْحابِهِ[[: «]]مَنْ يَشْتَري هذَيْنِ[[؟»]] فَقامَ رَجُلٌ فَقالَ[[: «]]أَنا أَشْتَريهِما بِدِرْهَمٍ[[».]] فَقالَ[[: «]]مَنْ يَزيدُ عَلى دِرْهَمٍ[[؟»]] فَقامَ رَجُلٌ آخَرُ وقالَ[[: «]]أَنا أَشْتَريهِما بِدِرْهَمَيْنِ[[».]] فَدَفَعَهُما إِلى الرَّسولِ ﷺ الَّذي سَلَّمَهُما إِلى الأَعْرابِيِّ قائِلًا[[: «]]اشْتَرِ بِأَحَدِهِما طَعامًا واذْهَبْ بِهِ إِلى أَهْلِكَ[[،]] واشْتَرِ بِالآخَرِ قَدومًا فَأْتِني بِهِ[[».]] فَأَتاهُ بِهِ[[،]] فَوَضَعَ فيهِ عودًا بِيَدِهِ[[،]] وقالَ لِلْأَعْرابِيِّ[[: «]]اذْهَبْ واحْتَطِبْ وبِعْ[[،]] ولا أَراكَ خَمْسَةَ عَشَرَ يَوْمًا[[».]] وبَعْدَ انْتِهاءِ هذِهِ المُدَّةِ رَجَعَ إِلَيْهِ الأَعْرابِيُّ وقَدِ اشْتَرَى ثِيابًا وطَعامًا[[،]] فَقالَ لَهُ الرَّسولُ ﷺ[[: «]]أَلَيْسَ هذا خَيْرًا لَكَ مِنْ أَنْ تَسْأَلَ النّاسَ أَعْطَوْكَ أَوْ مَنَعوكَ[[؟»]]"],
  ["", "حازِمٌ: هَلْ سَمِعْتَ قِصَّةَ الصَّحابِيِّ الَّذي عالَجَهُ الرَّسولُ ﷺ بِالعَسَلِ عِنْدَما اشْتَكَى مِنْ آلامٍ في بَطْنِهِ[[؟]]\nعامِرٌ: لا[[،]] لَمْ أَسْمَعْ بِها[[.]]\nحازِمٌ: لَقَدْ أَمَرَ الرَّسولُ ﷺ أَخاهُ أَنْ يَسْقِيَهُ عَسَلًا[[.]]\nعامِرٌ: وهَلْ شُفِيَ[[؟]]\nحازِمٌ: نَعَمْ[[،]] بَعْدَ أَنْ سَقاهُ ثَلاثَ مَرّاتٍ[[.]]\nعامِرٌ: العَسَلُ[[!]] سُبْحانَ اللهِ[[!]]\nحازِمٌ: نَعَمْ[[،]] العَسَلُ[[؛|،]] قالَ تَعالَى[[:]] ﴿فِيهِ شِفَاءٌ لِلنَّاسِ﴾[[.]]"]
];
